package cn.mint.tv;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicReference;
public class LanImportServerTest {
 LanImportServer server;URI uri;AtomicReference<String> imported=new AtomicReference<>();
 @Before public void start()throws Exception{server=new LanImportServer(InetAddress.getByName("127.0.0.1"),"local-page".getBytes(StandardCharsets.UTF_8),new LanImportServer.Importer(){public String link(String url){imported.set(url);return "链接已导入";}public String file(String name,byte[] bytes){imported.set(name+":"+new String(bytes,StandardCharsets.UTF_8));return "文件已导入";}});uri=new URI(server.url());}
 @After public void stop(){server.close();}
 String request(String method,String path,String headers,String body)throws Exception{byte[] bytes=body.getBytes(StandardCharsets.UTF_8);try(Socket socket=new Socket("127.0.0.1",uri.getPort())){socket.setSoTimeout(3000);String h=method+" "+path+" HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\n"+headers+"Content-Length: "+bytes.length+"\r\n\r\n";socket.getOutputStream().write(h.getBytes(StandardCharsets.US_ASCII));socket.getOutputStream().write(bytes);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=socket.getInputStream().read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 @Test public void servesOnlySecretSessionPage()throws Exception{assertTrue(request("GET",uri.getPath(),"","").contains("local-page"));assertTrue(request("GET","/wrong/","","").startsWith("HTTP/1.1 404"));}
 @Test public void importsHttpLinkAndReturnsReadableResult()throws Exception{String result=request("POST",uri.getPath()+"api/url","Content-Type: application/json\r\n","{\"url\":\"https://example.com/live.m3u\"}");assertTrue(result.startsWith("HTTP/1.1 200"));assertEquals("https://example.com/live.m3u",imported.get());assertTrue(result.contains("链接已导入"));}
 @Test public void uploadsRawUtf8FileWithoutMultipartMemoryOverhead()throws Exception{String name=java.net.URLEncoder.encode("频道列表.txt","UTF-8");String result=request("POST",uri.getPath()+"api/file","X-Mint-Filename: "+name+"\r\n","央视,http://example.com/live");assertTrue(result.startsWith("HTTP/1.1 200"));assertEquals("频道列表.txt:央视,http://example.com/live",imported.get());}
 @Test public void rejectsForeignWebOrigin()throws Exception{assertTrue(request("POST",uri.getPath()+"api/url","Origin: https://elsewhere.example\r\nContent-Type: application/json\r\n","{\"url\":\"https://example.com\"}").startsWith("HTTP/1.1 403"));assertNull(imported.get());}
 @Test public void rejectsNonHttpSubscription()throws Exception{assertTrue(request("POST",uri.getPath()+"api/url","Content-Type: application/json\r\n","{\"url\":\"file:///private\"}").startsWith("HTTP/1.1 400"));assertNull(imported.get());}
 @Test public void rejectsWrongFileType()throws Exception{assertTrue(request("POST",uri.getPath()+"api/file","X-Mint-Filename: app.apk\r\n","anything").startsWith("HTTP/1.1 400"));assertNull(imported.get());}
 @Test public void rejectsOversizeBeforeReceivingBody()throws Exception{try(Socket socket=new Socket("127.0.0.1",uri.getPort())){socket.setSoTimeout(3000);String h="POST "+uri.getPath()+"api/file HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\nContent-Length: 8388609\r\n\r\n";socket.getOutputStream().write(h.getBytes(StandardCharsets.US_ASCII));BufferedReader in=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));assertTrue(in.readLine().startsWith("HTTP/1.1 413"));}}
 @Test public void doesNotEnableCorsOrCacheSessionPage()throws Exception{String response=request("GET",uri.getPath(),"","");assertTrue(response.contains("Cache-Control: no-store"));assertFalse(response.contains("Access-Control-Allow-Origin"));assertTrue(response.contains("X-Frame-Options: DENY"));}
 @Test public void closesListenerWhenSessionEnds()throws Exception{int port=uri.getPort();server.close();assertFalse(server.active());try{new Socket("127.0.0.1",port).close();fail();}catch(IOException expected){}}
}
